from typing import List


def efficient_matching(set1: List[str], set2: List[str]) -> str:
    seen = set()
    for x in set1:
        seen.add(x)
    common = set()
    for x in set2:
        if x in seen:
            common.add(x)
    return " ".join(sorted(common)) if common else "NULL"

import java.util.*;

class Solution {
    String efficientMatching(String[] set1, String[] set2) {
        Set<String> s = new HashSet<>(Arrays.asList(set1));
        TreeSet<String> common = new TreeSet<>();
        for (String x : set2) if (s.contains(x)) common.add(x);
        if (common.isEmpty()) return "NULL";
        return String.join(" ", common);
    }
}

class Solution {
public:
    string efficientMatching(vector<string>& set1, vector<string>& set2) {
        unordered_set<string> s(set1.begin(), set1.end());
        set<string> common;
        for (auto& x : set2) if (s.count(x)) common.insert(x);
        if (common.empty()) return "NULL";
        string out;
        for (auto& v : common) { if (!out.empty()) out += " "; out += v; }
        return out;
    }
};
